contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint256 amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        require(amount == 10);
        require(address(this).balance >= amount);
        uint256 balBefore = address(this).balance;
        c.play{value: amount}(); if (__ESBMC_reverted()) return;
        uint256 balAfter = address(this).balance;
        // The player (this contract, which is also the bank) never loses more
        // than the 10-wei ticket: on a loss it pays exactly 10, on a win it
        // receives 9 as player plus 1 as bank, ending no worse than before.
        assert(balAfter + 10 >= balBefore);
    }

    receive() external payable {}
}

